import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    min_path = None

    for i in range(N):
        for j in range(N):
            visited = [[False] * N for _ in range(N)]
            visited[i][j] = True
            queue = [(grid[i][j], i, j, [(i, j)])]

            while queue:
                value, x, y, path = heapq.heappop(queue)

                if len(path) == k:
                    if min_path is None or path < min_path:
                        min_path = path[:]
                    continue

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if is_valid(nx, ny) and not visited[nx][ny]:
                        visited[nx][ny] = True
                        heapq.heappush(queue, (grid[nx][ny], nx, ny, path + [(nx, ny)]))

    return [grid[x][y] for x, y in min_path]
